style.css:
/* Fondo anime rosa y blanco */
html,
body {
    background: linear-gradient(
        135deg,
        #ffe4f1,
        #fff8fc,
        #ffc8e5
    ) !important;
    color: #b84d83 !important;
}

/* Paneles y elementos */
div,
section,
header {
    border-color: #ffd1e8;
}

/* Campos de búsqueda */
input,
textarea {
    background-color: #fff7fb !important;
    color: #b84d83 !important;
    border: 2px solid #ffc8e5 !important;
    border-radius: 18px !important;
}

/* Botones rosados */
button {
    background-color: #ffc8e5 !important;
    color: #8c3764 !important;
    border-radius: 14px !important;
    border: 1px solid #ffadd8 !important;
}

/* Selección de texto */
::selection {
    background: #ffadd8;
    color: white;
}
